using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void fit_timeline(Control o){var canvas=Field<Control>(o,"canvas");canvas.Set("scroll_time",0.0);canvas.Set("zoom",Math.Clamp((canvas.Size.X-174)/Math.Max(1,Document(o).Call("duration").AsDouble()+.5),8,1000));canvas.QueueRedraw();}
    public void edit_clip(Control o,string id){Session(o).Call("select",id);var clip=Document(o).Call("clip_for_id",id).AsGodotObject();var actor=Document(o).Call("actor_for_clip",id).AsGodotObject();if(clip==null||actor==null)return;var stream=workspace_source(Get(Dict(actor,"values"),"audio"));o.Set("_wave_clip_id",id);Field<Control>(o,"waveform").Call("open",stream==null?default(Variant):Variant.From(stream),clip.Get("source_offset"),clip.Get("duration").AsDouble()*clip.Get("playback_speed").AsDouble());var bottom=Field<TabContainer>(o,"bottom");bottom.Visible=true;bottom.CurrentTab=0;}
    public void loop_selection(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Stop the take before changing its transport loop.");return;}var selection=Field<Control>(o,"canvas").Get("time_selection").AsVector2();double start=selection.X,end=selection.Y;if(end<=start){start=double.PositiveInfinity;end=0;foreach(var id in Items(Session(o),"selected_ids")){var clip=Document(o).Call("clip_for_id",id).AsGodotObject();if(clip==null)continue;start=Math.Min(start,clip.Get("start_time").AsDouble());end=Math.Max(end,clip.Get("start_time").AsDouble()+clip.Get("duration").AsDouble());}}if(!double.IsFinite(start)||end<=start)return;SessionAction(o,"Loop selection",()=>{Document(o).Set("loop_start",start);Document(o).Set("loop_end",end);Document(o).Set("loop_enabled",true);});Field<Node>(o,"playback").Set("loop_enabled",true);automation_seek(o,start,false);
    }
    public void add_marker(Control o)=>name_dialog(o,"Add cue marker","Cue",Callable.From<string>(name=>SessionAction(o,"Add marker",()=>Items(Document(o),"markers").Add(new Settings{["id"]=NewAudioId(),["time"]=Position(o),["name"]=name}))),false);
    public void undo(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Stop or cancel the take before Undo.");return;}o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);o.Set("_controls_generation",o.Get("_controls_generation").AsInt64()+1);discard_parameter_handle(o);bool pending=Recording(o).Call("has_pending").AsBool();Recording(o).Call("discard",pending?"Read: pending automation discarded by Undo.":"Read: Undo requested.");Field<Timer>(o,"_automation_release_timer").Stop();o.Set("_automation_gesture_held",false);if(pending){Field<Node>(o,"playback").Call("stop",false);o.CallDeferred("_refresh_all");return;}Session(o).Call("undo");o.CallDeferred("_refresh_all");
    }
    public void redo(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Stop or cancel the take before Redo.");return;}o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);o.Set("_controls_generation",o.Get("_controls_generation").AsInt64()+1);discard_parameter_handle(o);Recording(o).Call("discard","Read: pending automation discarded before Redo.");Field<Timer>(o,"_automation_release_timer").Stop();o.Set("_automation_gesture_held",false);Field<Node>(o,"playback").Call("stop",false);Session(o).Call("redo");o.CallDeferred("_refresh_all");
    }
    public void chord_dialog(Control o)
    {
        if(Session(o).Call("primary_actor").AsGodotObject()==null)new_pattern(o,false);var dialog=window(o,"Insert chord",new Vector2I(400,240));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();int degree=0,inversion=0;NumberAction(o,host,"Scale degree",1,1,7,1,value=>degree=(int)value-1);NumberAction(o,host,"Inversion",0,0,2,1,value=>inversion=(int)value);ActionButton(host,"Insert editable notes",()=>{var actor=Session(o).Call("primary_actor").AsGodotObject();var clip=Session(o).Call("primary_clip").AsGodotObject();if(actor==null||clip==null||!Session(o).Call("can_edit",clip.Get("id")).AsBool())return;SessionAction(o,"Insert chord",()=>{var values=Dict(actor,"values");var notes=Get(values,"notes",new GArray()).AsGodotArray();using var composer=new AudioComposerOperations();foreach(var pitch in composer.chord(60+Document(o).Get("key").AsInt32(),Document(o).Get("scale").AsString(),degree,inversion,false))notes.Add(composer.new_note(pitch,Field<Control>(o,"piano").Get("scroll_beat").AsDouble(),1,.75,0));values[new StringName("notes")]=notes;values[new StringName("notes_dirty")]=true;Field<Control>(o,"piano").Call("_mark_changed");});render_dirty_notes(o);windowNode.QueueFree();});
    }
    public void apply_composer(Control o,Settings data)
    {
        using var composer=new AudioComposerControlOperations();string error=composer.apply_rendered(Session(o),data);if(error.Length>0){notice(o,error);return;}foreach(var id in Get(data,"applied_clip_ids",new GArray()).AsGodotArray()){var actor=Document(o).Call("actor_for_clip",id.AsString()).AsGodotObject();if(actor!=null)Dict(actor,"values")[new StringName("rendered_signature")]=note_render_key(o,actor);}fit_timeline(o);Field<Label>(o,"status").Text="Generated editable notes, harmony and arrangement sections.";
    }
    public void fit_notes_to_conductor_dialog(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()||Recording(o).Get("active").AsBool()||Recording(o).Call("has_pending").AsBool()){notice(o,"Finish recording before fitting note timing.");return;}var ids=Items(Session(o),"selected_ids").Duplicate();var owner=Session(o);var document=Document(o);long revision=owner.Get("revision").AsInt64();using var fit=new AudioConductorFitOperations();var prepared=fit.prepare(owner,ids);string error=Get(prepared,"error","").AsString();if(error.Length>0){notice(o,error);return;}var dialog=window(o,"Fit selected note sources to conductor",new Vector2I(660,440));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();label(host,"One-time re-map to the current step-tempo conductor. Clip starts remain at their absolute seconds; note pitches, source beat positions and linked patterns remain editable. Full clip lengths change. Existing local automation/fades stay in seconds. Trimmed, reversed, looped and stretched sources are refused. Future conductor edits still preserve source timing until you explicitly fit again.");foreach(var raw in prepared["operations"].AsGodotArray()){var operation=raw.AsGodotDictionary();label(host,operation["actor"].AsGodotObject().Get("display_name").AsString()+": "+operation["clip"].AsGodotObject().Get("duration").AsDouble().ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" → "+operation["duration"].AsDouble().ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" seconds");}ActionButton(host,"Apply timing policy · one Undo",()=>{if(Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision){notice(o,"The document changed. Review timing again.");return;}using var apply=new AudioConductorFitOperations();string problem=apply.apply(owner,ids);if(problem.Length>0)notice(o,problem);else{render_dirty_notes(o);windowNode.QueueFree();}});
    }
}
